# gf2lib.py -- written from scratch for TASK-20261002-997dbb (blind re-derivation J5).
# Pure-Python GF(2)[t] / GF(2^n) arithmetic on Python ints (bit j = coeff of t^j),
# binary-curve affine arithmetic, and numpy-vectorised helpers.
# No third-party code is used here except numpy for the vectorised layer.
import numpy as np

# ---------------------------------------------------------------- GF(2)[t]
def deg(a):
    return a.bit_length() - 1

def clmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r

def pmod(a, m):
    dm = m.bit_length()
    while a.bit_length() >= dm:
        a ^= m << (a.bit_length() - dm)
    return a

def pdivmod(a, m):
    q = 0
    dm = m.bit_length()
    while a.bit_length() >= dm:
        s = a.bit_length() - dm
        q ^= 1 << s
        a ^= m << s
    return q, a

def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a

def pmulmod(a, b, m):
    return pmod(clmul(a, b), m)

def ppowmod(a, e, m):
    r = 1
    a = pmod(a, m)
    while e:
        if e & 1:
            r = pmulmod(r, a, m)
        a = pmulmod(a, a, m)
        e >>= 1
    return pmod(r, m)

def int_prime_factors(n):
    out, d = [], 2
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        out.append(n)
    return out

def int_factor(n):
    """trial division; returns dict prime->exponent"""
    fac, d = {}, 2
    while d * d <= n:
        while n % d == 0:
            fac[d] = fac.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        fac[n] = fac.get(n, 0) + 1
    return fac

def is_irreducible_benor(f):
    """Ben-Or: f (deg n) irreducible iff gcd(f, t^(2^i) - t) = 1 for i = 1..floor(n/2)."""
    n = deg(f)
    if n < 1:
        return False
    u = 2
    for _ in range(1, n // 2 + 1):
        u = pmulmod(u, u, f)
        if pgcd(f, u ^ pmod(2, f)) != 1:
            return False
    return True

def is_irreducible_rabin(f):
    """Rabin: t^(2^n) = t mod f and gcd(f, t^(2^(n/q)) - t) = 1 for every prime q | n."""
    n = deg(f)
    if n < 1:
        return False
    t = pmod(2, f)
    u = t
    for _ in range(n):
        u = pmulmod(u, u, f)
    if u != t:
        return False
    for qq in int_prime_factors(n):
        u = t
        for _ in range(n // qq):
            u = pmulmod(u, u, f)
        if pgcd(f, u ^ t) != 1:
            return False
    return True

def is_irreducible_trialdiv(f):
    """brute force: no factor of degree 1..floor(n/2) (all polys of that degree tried)."""
    n = deg(f)
    for d in range(1, n // 2 + 1):
        for g in range(1 << d, 1 << (d + 1)):
            if pmod(f, g) == 0:
                return False
    return True

# ---------------------------------------------------------------- GF(2^n)
class F2n:
    def __init__(self, f):
        self.f = f
        self.n = deg(f)
        self.q = 1 << self.n

    def mul(self, a, b):
        return pmulmod(a, b, self.f)

    def sqr(self, a):
        return pmulmod(a, a, self.f)

    def pow(self, a, e):
        return ppowmod(a, e, self.f)

    def inv(self, a):
        if a == 0:
            raise ZeroDivisionError
        r0, r1 = self.f, a
        s0, s1 = 0, 1
        while r1 != 1:
            qq, r = pdivmod(r0, r1)
            if r == 0:
                raise ValueError("not invertible")
            r0, r1 = r1, r
            s0, s1 = s1, s0 ^ clmul(qq, s1)
        return pmod(s1, self.f)

    def tr(self, a):
        s = t = a
        for _ in range(self.n - 1):
            t = self.sqr(t)
            s ^= t
        assert s in (0, 1), s
        return s

    def htr(self, a):
        assert self.n % 2 == 1
        s = t = a
        for _ in range((self.n - 1) // 2):
            t = self.sqr(self.sqr(t))
            s ^= t
        return s

    def sqrt(self, a):
        return self.pow(a, 1 << (self.n - 1))

    def conj(self, w):
        out, c = [], w
        for _ in range(self.n):
            out.append(c)
            c = self.sqr(c)
        assert c == w
        return out

# ---------------------------------------------------------------- GF(2) linear algebra
def gauss_jordan_inverse(rows, n):
    """rows[i] = int, bit j = B[i][j].  Returns rows of B^{-1} (same convention) or None."""
    A = list(rows)
    I = [1 << i for i in range(n)]
    for col in range(n):
        piv = None
        for r in range(col, n):
            if (A[r] >> col) & 1:
                piv = r
                break
        if piv is None:
            return None
        A[col], A[piv] = A[piv], A[col]
        I[col], I[piv] = I[piv], I[col]
        for r in range(n):
            if r != col and (A[r] >> col) & 1:
                A[r] ^= A[col]
                I[r] ^= I[col]
    assert all(A[i] == (1 << i) for i in range(n))
    return I

def gf2_rank(rows):
    rows = [r for r in rows if r]
    rank = 0
    while rows:
        p = max(rows)
        hb = p.bit_length() - 1
        rows = [r ^ p if (r >> hb) & 1 else r for r in rows if r != p]
        rows = [r for r in rows if r]
        rank += 1
    return rank

# ---------------------------------------------------------------- binary curve, affine
class Curve:
    """y^2 + x y = x^3 + A x^2 + B over F; points are (x, y) tuples, None = infinity."""
    def __init__(self, F, A, B):
        self.F, self.A, self.B = F, A, B

    def on_curve(self, P):
        if P is None:
            return True
        F = self.F
        x, y = P
        lhs = F.sqr(y) ^ F.mul(x, y)
        x2 = F.sqr(x)
        rhs = F.mul(x2, x) ^ F.mul(self.A, x2) ^ self.B
        return lhs == rhs

    def neg(self, P):
        if P is None:
            return None
        return (P[0], P[0] ^ P[1])

    def dbl(self, P):
        if P is None:
            return None
        F = self.F
        x1, y1 = P
        if x1 == 0:
            return None
        lam = x1 ^ F.mul(y1, F.inv(x1))
        x3 = F.sqr(lam) ^ lam ^ self.A
        y3 = F.sqr(x1) ^ F.mul(lam, x3) ^ x3
        return (x3, y3)

    def add(self, P, Q):
        if P is None:
            return Q
        if Q is None:
            return P
        F = self.F
        x1, y1 = P
        x2, y2 = Q
        if x1 == x2:
            if y1 == y2:
                return self.dbl(P)
            return None
        lam = F.mul(y1 ^ y2, F.inv(x1 ^ x2))
        x3 = F.sqr(lam) ^ lam ^ x1 ^ x2 ^ self.A
        y3 = F.mul(lam, x1 ^ x3) ^ x3 ^ y1
        return (x3, y3)

    def smul(self, k, P):
        R = None
        for bit in bin(k)[2:]:
            R = self.dbl(R)
            if bit == '1':
                R = self.add(R, P)
        return R

    def points_over_x(self, x):
        F = self.F
        if x == 0:
            return [(0, F.sqrt(self.B))]
        c = x ^ self.A ^ F.mul(self.B, F.sqr(F.inv(x)))
        if F.tr(c):
            return []
        z = F.htr(c)
        assert F.sqr(z) ^ z == c
        y = F.mul(x, z)
        return [(x, y), (x, y ^ x)]

# ---------------------------------------------------------------- vectorised layer
class VecField:
    """numpy int64 arrays of field elements; linear maps by 8-bit chunk tables;
    multiplication by discrete-log tables built from a primitive element."""
    def __init__(self, F, build_tables=True):
        self.F = F
        self.n, self.q, self.f = F.n, F.q, F.f
        n = self.n
        self.sq_tabs = self.lin_tables([F.sqr(1 << j) for j in range(n)])
        self.tr_mask = sum(F.tr(1 << j) << j for j in range(n))
        if build_tables:
            self.build_log_tables()

    def lin_tables(self, images):
        n = self.n
        tabs = []
        for c0 in range(0, n, 8):
            width = min(8, n - c0)
            T = np.zeros(1 << width, dtype=np.int64)
            for v in range(1 << width):
                acc = 0
                for b in range(width):
                    if (v >> b) & 1:
                        acc ^= images[c0 + b]
                T[v] = acc
            tabs.append((c0, width, T))
        return tabs

    @staticmethod
    def lin_apply(tabs, x):
        out = np.zeros_like(x)
        for c0, width, T in tabs:
            out ^= T[(x >> c0) & ((1 << width) - 1)]
        return out

    def mulconst_tabs(self, c):
        F = self.F
        return self.lin_tables([F.mul(c, 1 << j) for j in range(self.n)])

    def sqr(self, x):
        return self.lin_apply(self.sq_tabs, x)

    def tr(self, x):
        return (np.bitwise_count(x & self.tr_mask) & 1).astype(np.int64)

    def find_generator(self):
        F, q = self.F, self.q
        ps = int_prime_factors(q - 1)
        g = 2
        while True:
            if all(F.pow(g, (q - 1) // p) != 1 for p in ps):
                return g
            g += 1

    def build_log_tables(self):
        F, q = self.F, self.q
        g = self.find_generator()
        self.g = g
        EXP = np.zeros(q - 1, dtype=np.int64)
        EXP[0] = 1
        size = 1
        gp = g
        while size < q - 1:
            m = min(size, q - 1 - size)
            EXP[size:size + m] = self.lin_apply(self.mulconst_tabs(gp), EXP[:m])
            size += m
            gp = F.sqr(gp)
        # sanity: permutation of 1..q-1 and closure g^(q-1) = 1
        assert EXP.min() >= 1 and EXP.max() <= q - 1
        assert np.unique(EXP).size == q - 1
        assert F.mul(int(EXP[-1]), g) == 1
        LOG = np.zeros(q, dtype=np.int64)
        LOG[EXP] = np.arange(q - 1, dtype=np.int64)
        self.EXP, self.LOG = EXP, LOG
        INV = np.zeros(q, dtype=np.int64)
        k = np.arange(q - 1, dtype=np.int64)
        INV[EXP] = EXP[(-k) % (q - 1)]
        self.INV = INV

    def mul(self, a, b):
        qm1 = self.q - 1
        s = self.LOG[a] + self.LOG[b]
        s = np.where(s >= qm1, s - qm1, s)
        r = self.EXP[s]
        r = np.where((a == 0) | (b == 0), 0, r)
        return r

    def mul_clmul(self, a, b):
        """independent vectorised multiply: shift-and-add then reduce (no tables)."""
        n, f = self.n, self.f
        r = np.zeros_like(a)
        for i in range(n):
            r ^= np.where((b >> i) & 1, a << i, 0)
        for d in range(2 * n - 2, n - 1, -1):
            r ^= np.where((r >> d) & 1, f << (d - n), 0)
        return r

