# xcheck_pure.py -- second, independent implementation (pure Python, no numpy) for TASK-20261002-997dbb.
# usage: python3 xcheck_pure.py CELL-ID [inclusive|narrow] [affine_sample_size or 'all']
# Independent of q2_enum.py: inverses from powers of a generator, coordinates from a Gray-code
# forward map (not Gauss-Jordan), cosets from the definitional doubling image and checked by
# affine double-and-add [#E/4]P / [#E/2]P, labels from bit strings, statistics from dicts.
import json, sys, time, random
from fractions import Fraction
from math import comb
from multiprocessing import Pool
from gf2lib import F2n, Curve, int_prime_factors

T0 = time.time()
cell_id = sys.argv[1]
reading = sys.argv[2] if len(sys.argv) > 2 else 'inclusive'
samp_arg = sys.argv[3] if len(sys.argv) > 3 else 'all'
Q1 = json.load(open('q1_results.json'))
rec = [c for c in Q1['cells'] if c['cell'] == cell_id and c['typeII_reading'] == reading][0]
n, A, B = rec['n'], rec['A'], rec['B']
f, w, NE = rec['field_poly_int'], rec['normal_element_w'], rec['group_order']
KOB = cell_id.startswith('CELL-K')
F = F2n(f)
q = F.q
E = Curve(F, A, B)
LOG = []
def P(*a):
    s = ' '.join(str(x) for x in a)
    print(s, flush=True)
    LOG.append(s)

# ---- inverses from powers of a primitive element (pure Python)
ps = int_prime_factors(q - 1)
g = 2
while not all(F.pow(g, (q - 1) // p) != 1 for p in ps):
    g += 1
pw = [0] * (q - 1)
cur = 1
for k in range(q - 1):
    pw[k] = cur
    cur = F.mul(cur, g)
assert cur == 1
INV = [0] * q
for k in range(q - 1):
    INV[pw[k]] = pw[(q - 1 - k) % (q - 1)]
del pw
P('inverse table built', round(time.time() - T0, 1))
# spot-check inverses with extended Euclid
rng = random.Random(5)
for _ in range(2000):
    x = rng.randrange(1, q)
    assert INV[x] == F.inv(x)

# ---- trace / squaring helpers
trmask = 0
for j in range(n):
    if F.tr(1 << j):
        trmask |= 1 << j
def tr(x):
    return bin(x & trmask).count('1') & 1
sqtab = [F.sqr(1 << j) for j in range(n)]
def sqr(x):
    r, j = 0, 0
    while x:
        if x & 1:
            r ^= sqtab[j]
        x >>= 1
        j += 1
    return r
def mulB(x):
    return F.mul(B, x)

# ---- points per x
trA = tr(A)
npts = [0] * q
npts[0] = 1
for x in range(1, q):
    if tr(x ^ A ^ mulB(sqr(INV[x]))) == 0:
        npts[x] = 2
naff = sum(npts)
assert naff + 1 == NE, (naff + 1, NE)
P('affine points', naff, round(time.time() - T0, 1))

# ---- definitional 2E, 4E (x-coordinates)
def dblx(x):
    return sqr(x) ^ mulB(sqr(INV[x]))
in2 = bytearray(q)
for x in range(1, q):
    if npts[x]:
        in2[dblx(x)] = 1
in4 = bytearray(q)
for x in range(1, q):
    if in2[x]:
        in4[dblx(x)] = 1
P('2E/4E images built', round(time.time() - T0, 1))
if KOB:
    ctype = [(-1 if not npts[x] else (0 if in4[x] else (2 if in2[x] else 1))) for x in range(q)]
else:
    ctype = [(-1 if not npts[x] else (0 if in2[x] else 1)) for x in range(q)]

# ---- affine double-and-add check of the coset type
xs_on = [x for x in range(q) if npts[x]]
if samp_arg == 'all':
    chk = xs_on
else:
    chk = random.Random(77).sample(xs_on, int(samp_arg))
K = NE // 4 if KOB else NE // 2
def affine_type(x):
    Pt = E.points_over_x(x)[0]
    R = E.smul(K, Pt)
    if R is None:
        return 0
    if R[0] == 0:
        return 2 if KOB else 1
    return 1   # a 4-torsion point (Koblitz only)
def worker(chunk):
    return [affine_type(x) for x in chunk]
nproc = 4
chunks = [chk[i::nproc] for i in range(nproc)]
with Pool(nproc) as pool:
    res = pool.map(worker, chunks)
bad = 0
for ch, rr in zip(chunks, res):
    for x, t in zip(ch, rr):
        if t != ctype[x]:
            bad += 1
P('affine double-and-add coset check on', len(chk), 'x values; mismatches:', bad, round(time.time() - T0, 1))
assert bad == 0

# ---- normal-basis coordinates by forward Gray-code map (no Gauss-Jordan)
rows = F.conj(w)
fwd = [0] * q
for c in range(1, q):
    low = (c & -c).bit_length() - 1
    fwd[c] = fwd[c & (c - 1)] ^ rows[low]
Cmap = [-1] * q
for c in range(q):
    Cmap[fwd[c]] = c
assert min(Cmap) >= 0
del fwd
P('coordinates built', round(time.time() - T0, 1))

# ---- labels from strings
def sA_of(c):          # c_0 first
    return ''.join('1' if (c >> i) & 1 else '0' for i in range(n))
def lexmin_rot(s):
    return min(s[i:] + s[:i] for i in range(n))
def f1_class(M, wt, mode):
    p_lt = Fraction(sum(comb(n, j) for j in range(wt)), 2 ** n)
    p_eq = Fraction(comb(n, wt), 2 ** n)
    if mode == 'mid':
        v = p_lt + p_eq / 2
        return int(v * M)            # floor (v > 0)
    if mode == 'mid_ceil_minus_1':
        v = (p_lt + p_eq / 2) * M
        return -((-v.numerator) // v.denominator) - 1
    if mode == 'left_floor':
        return int(p_lt * M)
    if mode == 'right_ceil_minus_1':
        v = (p_lt + p_eq) * M
        return -((-v.numerator) // v.denominator) - 1
    if mode == 'cdf_floor_capped':
        return min(M - 1, int((p_lt + p_eq) * M))
F1CACHE = {}
def f1(M, wt, mode='mid'):
    key = (M, wt, mode)
    if key not in F1CACHE:
        F1CACHE[key] = f1_class(M, wt, mode)
    return F1CACHE[key]

ALPH = rec['row_alphabets']
# label spec list: (name, family, offset, M, f5, fn(x, c, sA, sB, ...) )
specs = []
for M in ALPH:
    r = M.bit_length() - 1
    offs = [0, (n - r) // 2, n - r]
    r4 = r - 2
    if KOB:
        specs.append(('F1', None, M, False, 'mid', lambda d, M=M: f1(M, d['wt'])))
        for o in offs:
            specs.append(('F2', o, M, False, 'p', lambda d, o=o, r=r: d['sA2'][o:o + r]))
        for o in offs:
            specs.append(('F3', o, M, False, 'p', lambda d, o=o, r=r: d['px'][o:o + r]))
        specs.append(('F4', None, M, False, 'a', lambda d, r=r: d['mA'][:r]))
        specs.append(('F5[F1]', None, M, True, 'mid', lambda d, M=M: f1(M // 4, d['wt'])))
        specs.append(('F5[F2@0]', 0, M, True, 'p', lambda d, r4=r4: d['sA2'][0:r4]))
        specs.append(('F5[F3@0]', 0, M, True, 'p', lambda d, r4=r4: d['px'][0:r4]))
        specs.append(('F5[F4]', None, M, True, 'a', lambda d, r4=r4: d['mA'][:r4]))
        for mode in ('mid_ceil_minus_1', 'left_floor', 'right_ceil_minus_1', 'cdf_floor_capped'):
            specs.append(('F1', None, M, False, 'F1:' + mode, lambda d, M=M, mode=mode: f1(M, d['wt'], mode)))
            specs.append(('F5[F1]', None, M, True, 'F1:' + mode, lambda d, M=M, mode=mode: f1(M // 4, d['wt'], mode)))
        for mode in ('b', 'c', 'd'):
            if mode == 'b':
                fn = lambda d, r=r: d['mB'][:r]
                fn5 = lambda d, r4=r4: d['mB'][:r4]
            elif mode == 'c':
                fn = lambda d, r=r: d['mB'][n - r:]
                fn5 = lambda d, r4=r4: d['mB'][n - r4:] if r4 else ''
            else:
                fn = lambda d, r=r: d['mA'][n - r:]
                fn5 = lambda d, r4=r4: d['mA'][n - r4:] if r4 else ''
            specs.append(('F4', None, M, False, 'F4:' + mode, fn))
            specs.append(('F5[F4]', None, M, True, 'F4:' + mode, fn5))
        for o in range(n):
            specs.append(('F2', o, M, False, 'F2:all_cyclic_offsets', lambda d, o=o, r=r: d['sA2'][o:o + r]))
            specs.append(('F5[F2@o]', o, M, True, 'F5[F2]:all_cyclic_offsets', lambda d, o=o, r4=r4: d['sA2'][o:o + r4]))
        for s in range(n - r + 1):
            specs.append(('F3', s, M, False, 'F3:all_windows', lambda d, s=s, r=r: d['px'][s:s + r]))
        for s in range(n - r4 + 1):
            specs.append(('F5[F3@s]', s, M, True, 'F5[F3]:all_windows', lambda d, s=s, r4=r4: d['px'][s:s + r4]))
    else:
        for o in offs:
            specs.append(('ORD-F2', o, M, False, 'p', lambda d, o=o, r=r: d['sA2'][o:o + r]))
        for o in offs:
            specs.append(('ORD-F3', o, M, False, 'p', lambda d, o=o, r=r: d['px'][o:o + r]))
        for o in range(n):
            specs.append(('ORD-F2', o, M, False, 'F2:all_cyclic_offsets', lambda d, o=o, r=r: d['sA2'][o:o + r]))
        for s in range(n - r + 1):
            specs.append(('ORD-F3', s, M, False, 'F3:all_windows', lambda d, s=s, r=r: d['px'][s:s + r]))
if not KOB:
    M, r = 32, 5
    for o in [0, (n - r) // 2, n - r]:
        specs.append(('ORD-F2', o, M, False, 'RM_rounding:M32', lambda d, o=o, r=r: d['sA2'][o:o + r]))
    for o in [0, (n - r) // 2, n - r]:
        specs.append(('ORD-F3', o, M, False, 'RM_rounding:M32', lambda d, o=o, r=r: d['px'][o:o + r]))

NC = 4 if KOB else 2
def agg_chunk(bounds):
    lo, hi = bounds
    hs = [dict() for _ in specs]
    for x in range(lo, hi):
        t = ctype[x]
        if t < 0:
            continue
        c = Cmap[x]
        sA = sA_of(c)
        d = dict(wt=sA.count('1'), sA2=sA + sA, px=format(x, '0%db' % n)[::-1],
                 mA=lexmin_rot(sA), mB=lexmin_rot(sA[::-1]))
        if KOB and t == 1:
            contrib = ((1, 1), (3, 1))
        else:
            contrib = ((t, npts[x]),)
        for i, sp in enumerate(specs):
            lab = sp[5](d)
            h = hs[i]
            for cid, m in contrib:
                key = (lab, cid) if sp[3] else lab
                v = h.get(key)
                if v is None:
                    v = [0] * NC
                    h[key] = v
                v[cid] += m
    return hs
NCH = 32
bounds = [(q * i // NCH, q * (i + 1) // NCH) for i in range(NCH)]
with Pool(nproc) as pool:
    parts = pool.map(agg_chunk, bounds, chunksize=1)
hists = [dict() for _ in specs]
for hs in parts:
    for i, h in enumerate(hs):
        H = hists[i]
        for k, v in h.items():
            if k in H:
                H[k] = [a + b for a, b in zip(H[k], v)]
            else:
                H[k] = list(v)
del parts
P('labels aggregated', round(time.time() - T0, 1))

GROUPS2 = [[0, 2], [1, 3]] if KOB else [[0], [1]]
def stats(h):
    sizes = {k: sum(v) for k, v in h.items()}
    ne = {k: s for k, s in sizes.items() if s > 0}
    out = dict(n_classes=len(ne), min_class=min(ne.values()), max_class=max(ne.values()))
    tot = sum(ne.values())
    assert tot == NE - 1
    pure2 = sum(s for k, s in ne.items() if sum(1 for gg in GROUPS2 if sum(h[k][j] for j in gg) > 0) == 1)
    c2 = 0
    for gg in GROUPS2:
        col = [sum(v[j] for j in gg) for v in h.values()]
        c2 += sum(col) - max(col)
    p2 = Fraction(pure2, tot)
    out['c2'] = c2
    out['purity2'] = '%d/%d' % (p2.numerator, p2.denominator)
    if KOB:
        pure4 = sum(s for k, s in ne.items() if sum(1 for j in range(4) if h[k][j] > 0) == 1)
        p4 = Fraction(pure4, tot)
        c4 = 0
        for j in range(4):
            col = [v[j] for v in h.values()]
            c4 += sum(col) - max(col)
        out['c4'] = c4
        out['purity4'] = '%d/%d' % (p4.numerator, p4.denominator)
    return out

mine = []
for sp, h in zip(specs, hists):
    d = dict(family=sp[0], offset=sp[1], M=sp[2], variant=sp[4])
    d.update(stats(h))
    mine.append(d)

# ---- compare with q2_enum.py output
tag = cell_id + ('' if reading == 'inclusive' else '_narrow')
Q2 = json.load(open('q2_%s.json' % tag))
def keyof(dd, variant):
    return (dd['family'], dd['offset'], dd['M'], variant)
ref = {}
for dd in Q2['rows']:
    v = 'p' if dd['family'] not in ('F1', 'F4', 'F5[F1]', 'F5[F4]') else ('mid' if 'F1' in dd['family'] else 'a')
    ref[keyof(dd, v)] = dd
for dd in Q2['sensitivity']:
    ref[keyof(dd, dd['variant'])] = dd
FIELDS = ['n_classes', 'min_class', 'max_class', 'c2', 'purity2'] + (['c4', 'purity4'] if KOB else [])
nmatch = nmis = 0
for dd in mine:
    k = keyof(dd, dd['variant'])
    rr = ref.get(k)
    if rr is None:
        P('NO REFERENCE ROW FOR', k)
        nmis += 1
        continue
    diffs = {fl: (dd[fl], rr[fl]) for fl in FIELDS if dd[fl] != rr[fl]}
    if diffs:
        nmis += 1
        P('MISMATCH', k, diffs)
    else:
        nmatch += 1
P('rows compared: match', nmatch, 'mismatch', nmis, 'of', len(mine), '; reference rows', len(ref))
json.dump(dict(cell=cell_id, reading=reading, rows=mine, match=nmatch, mismatch=nmis,
               affine_checked=len(chk), seconds=round(time.time() - T0, 1)),
          open('xcheck_%s.json' % tag, 'w'), indent=0)
open('xcheck_%s_log.txt' % tag, 'w').write('\n'.join(LOG) + '\n')
P('done', round(time.time() - T0, 1), 's')
assert nmis == 0

sens_summary.py.text:
# sens_summary.py -- condense the sensitivity rows of q2_*.json into Q0 dependence statements.
import json
FIELDS_K = ['n_classes', 'min_class', 'max_class', 'c2', 'purity2', 'c4', 'purity4']
FIELDS_O = ['n_classes', 'min_class', 'max_class', 'c2', 'purity2']
OUT = {}
def tup(d, fields):
    return tuple(d[k] for k in fields)
def brief(d, fields):
    return {k: d[k] for k in fields}
for tag in ['CELL-K13', 'CELL-K19', 'CELL-K23', 'CELL-O19']:
    Q = json.load(open('q2_%s.json' % tag))
    n = Q['n']
    KOB = tag.startswith('CELL-K')
    FL = FIELDS_K if KOB else FIELDS_O
    prim = {(d['family'], d['offset'], d['M']): d for d in Q['rows']}
    S = Q['sensitivity']
    res = {}
    if KOB:
        # F1 readings
        f1 = []
        for d in S:
            if d['variant'].startswith('F1:'):
                base = prim[(d['family'], None, d['M'])]
                ch = {k: (base[k], d[k]) for k in FL if base[k] != d[k]}
                f1.append(dict(family=d['family'], M=d['M'], reading=d['variant'][3:],
                               changed=ch if ch else 'identical'))
        res['F1_readings'] = f1
        # F4 readings
        f4 = []
        for d in S:
            if d['variant'].startswith('F4:'):
                base = prim[(d['family'], None, d['M'])]
                ch = {k: (base[k], d[k]) for k in FL if base[k] != d[k]}
                f4.append(dict(family=d['family'], M=d['M'], reading=d['variant'][3:],
                               changed=ch if ch else 'identical'))
        res['F4_readings'] = f4
        # F2 offset invariance (all n cyclic offsets) for F2 and F5[F2@o]
        inv = {}
        for fam, var in (('F2', 'F2:all_cyclic_offsets'), ('F5[F2@o]', 'F5[F2]:all_cyclic_offsets')):
            for M in sorted({d['M'] for d in S if d['variant'] == var}):
                vals = {tup(d, FL) for d in S if d['variant'] == var and d['M'] == M}
                inv['%s_M%d' % (fam, M)] = {'offsets_tested': n, 'distinct_statistics': len(vals)}
        res['F2_offset_invariance'] = inv
    # F3 windows: primary offsets vs counted-from-the-top reading s = n - r - o
    f3 = []
    fam3 = 'F3' if KOB else 'ORD-F3'
    var3 = 'F3:all_windows'
    allw = {(d['M'], d['offset']): d for d in S if d['variant'] == var3 and d['family'] == fam3}
    for M in sorted({d['M'] for d in Q['rows']}):
        r = M.bit_length() - 1
        for o in (0, (n - r) // 2, n - r):
            s = n - r - o
            a, b = allw[(M, o)], allw[(M, s)]
            ch = {k: (a[k], b[k]) for k in FL if a[k] != b[k]}
            f3.append(dict(M=M, offset_from_bit0=o, same_window_counted_from_top_is_bit_offset=s,
                           changed=ch if ch else 'identical'))
        vals = [allw[(M, s)] for s in range(n - r + 1)]
        f3.append(dict(M=M, all_windows_range={k: [min(v[k] for v in vals), max(v[k] for v in vals)]
                                              for k in FL if not k.startswith('purity')},
                       purity2_values=sorted({v['purity2'] for v in vals})))
    res['F3_window_direction'] = f3
    if not KOB:
        # ORD-F2 orientation / index-0 dependence: all 19 cyclic offsets
        f2 = []
        allo = {(d['M'], d['offset']): d for d in S if d['variant'] == 'F2:all_cyclic_offsets'}
        for M in sorted({d['M'] for d in Q['rows']}):
            r = M.bit_length() - 1
            for o in (0, (n - r) // 2, n - r):
                # reversed coordinate order (index i <-> w^(2^(n-1-i))) maps window o to n - r - o
                s = n - r - o
                a, b = allo[(M, o)], allo[(M, s)]
                ch = {k: (a[k], b[k]) for k in FL if a[k] != b[k]}
                f2.append(dict(M=M, offset=o, reversed_index_equivalent_offset=s, changed=ch if ch else 'identical'))
            vals = [allo[(M, o)] for o in range(n)]
            f2.append(dict(M=M, all_19_cyclic_offsets_range={k: [min(v[k] for v in vals), max(v[k] for v in vals)]
                                                             for k in FL if not k.startswith('purity')},
                           purity2_values=sorted({v['purity2'] for v in vals})))
        res['ORD_F2_index_orientation'] = f2
        res['RM_rounding_M32_rows'] = [brief(d, ['family', 'offset', 'M'] + FL) for d in S if d['variant'] == 'RM_rounding:M32']
    OUT[tag] = res
# K23 narrow vs inclusive
A = json.load(open('q2_CELL-K23.json'))
Bn = json.load(open('q2_CELL-K23_narrow.json'))
pa = {(d['family'], d['offset'], d['M']): d for d in A['rows']}
diff = []
for d in Bn['rows']:
    k = (d['family'], d['offset'], d['M'])
    a = pa[k]
    ch = [f for f in FIELDS_K if a[f] != d[f]]
    diff.append(dict(family=d['family'], offset=d['offset'], M=d['M'], fields_changed=ch))
OUT['K23_typeII_reading'] = dict(rows=len(diff), rows_with_any_change=sum(1 for x in diff if x['fields_changed']),
                                 rows_unchanged=[(x['family'], x['offset'], x['M']) for x in diff if not x['fields_changed']])
json.dump(OUT, open('sens_summary.json', 'w'), indent=1)
print(json.dumps(OUT, indent=1)[:20000])

